import './App.css';
import Header from './components/Header';
import Calendar from './components/Calendar';
import Table from './components/Table';

function App() {
  const [range, setRange] = useState([
    {
        startDate: new Date(),
        endDate: new Date(),
        key: 'selection'
    }
]);

  return (
    <div className="App">
      <Header />
      <Calendar />
      <Table />
    </div>
  );
}

export default App;
